// Helpers shared by the native emitters (Swift and Kotlin).
//
// Only semantic and component tokens are emitted for native platforms. Primitives are an
// implementation detail of the token source; components must not use them, so the native
// APIs do not offer them.
import { rgba } from "../color.js";
import { DENSITIES, MODES } from "../load.js";
import { resolvedType, resolveToken } from "../resolve.js";

export const HEADER =
  "// GENERATED by raincoat-tokens from the token source. Do not edit: change tokens/ and rebuild.";

const FONT_WEIGHTS = {
  thin: 100,
  hairline: 100,
  "extra-light": 200,
  "ultra-light": 200,
  light: 300,
  normal: 400,
  regular: 400,
  book: 400,
  medium: 500,
  "semi-bold": 600,
  "demi-bold": 600,
  bold: 700,
  "extra-bold": 800,
  "ultra-bold": 800,
  black: 900,
  heavy: 900,
  "extra-black": 950,
  "ultra-black": 950,
};

export const pascal = (segment) =>
  segment
    .split("-")
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join("");
export const camel = (segment) => {
  const name = pascal(segment);
  return name[0].toLowerCase() + name.slice(1);
};

/** A number without floating-point noise: 0.1 + 0.2 becomes 0.3. */
export const tidy = (value) => Number(value.toFixed(4));
/** A dimension in points (dp, sp): rem is converted at 16 per rem. */
export const points = ({ value, unit }) => (unit === "rem" ? value * 16 : value);
export const seconds = ({ value, unit }) => (unit === "ms" ? value / 1000 : value);
export const milliseconds = ({ value, unit }) => (unit === "s" ? value * 1000 : value);
export const weight = (value) => FONT_WEIGHTS[value] ?? value;
export const families = (value) => [].concat(value);

/** A color as hex digits: {rgb: "f7d22a", alpha: 1, alphaByte: "ff"}. */
export function hexParts(value) {
  const { r, g, b, a } = rgba(value);
  const byte = (channel) =>
    Math.round(channel * 255)
      .toString(16)
      .padStart(2, "0");
  return { rgb: `${byte(r)}${byte(g)}${byte(b)}`, alpha: a, alphaByte: byte(a) };
}

/**
 * A resolved value in canonical text form. The native packages each have a `TokenFormat` that
 * writes the values they were compiled with in this same form, and their contract tests
 * compare the two. It is deliberately separate from the code that writes native literals.
 */
export function canonical(type, value) {
  const fixed = (n) => n.toFixed(4);
  switch (type) {
    case "color": {
      const { rgb, alpha, alphaByte } = hexParts(value);
      return `#${rgb}${alpha < 1 ? alphaByte : ""}`;
    }
    case "dimension":
      return fixed(points(value));
    case "duration":
      return fixed(seconds(value));
    case "number":
      return fixed(value);
    case "fontWeight":
      return String(weight(value));
    case "fontFamily":
      return families(value).join(", ");
    case "cubicBezier":
      return value.map(fixed).join(",");
    case "typography":
      return [
        canonical("fontFamily", value.fontFamily),
        fixed(points(value.fontSize)),
        String(weight(value.fontWeight)),
        fixed(points(value.letterSpacing)),
        fixed(value.lineHeight),
      ].join("|");
    default:
      throw new Error(`native emitters do not support the type "${type}" yet`);
  }
}

/** The semantic and component tokens as a tree of groups, each leaf with its resolved value. */
export function tree(tokens) {
  const root = { path: [], groups: new Map(), leaves: [] };
  for (const token of tokens.values()) {
    if (token.tier === "primitive") continue;
    let node = root;
    for (const segment of token.path.slice(0, -1)) {
      if (!node.groups.has(segment)) {
        node.groups.set(segment, { path: [...node.path, segment], groups: new Map(), leaves: [] });
      }
      node = node.groups.get(segment);
    }
    node.leaves.push({
      token,
      segment: token.path.at(-1),
      type: resolvedType(token.id, tokens),
      value: resolveToken(token.id, tokens),
    });
  }
  return root;
}

/** A group and every group beneath it, depth first. */
export function* groupsOf(node) {
  yield node;
  for (const child of node.groups.values()) yield* groupsOf(child);
}

export const indent = (text, depth) =>
  text
    .split("\n")
    .map((line) => (line === "" ? "" : `${"    ".repeat(depth)}${line}`))
    .join("\n");

/** Every combination of color mode and density, in a fixed order. */
export const permutations = () =>
  MODES.flatMap((mode) => DENSITIES.map((density) => ({ mode, density })));

/** The id and canonical value of every exposed token in a composed set. */
export const expectedEntries = (tokens) =>
  [...tokens.values()]
    .filter((token) => token.tier !== "primitive")
    .map((token) => [
      token.id,
      canonical(resolvedType(token.id, tokens), resolveToken(token.id, tokens)),
    ]);
